from packaging.version import Version


def create_version(version_string: str) -> str:
    """Parse and create a Version object from a version string for comparison and manipulation. version_string: A string representation of a version conforming to PEP 440, e.g. '1.0a5' -> '<Version('1.0a5')>'."""
    try:
        version = Version(version_string)
        return str(version)
    except Exception as e:
        raise ValueError(f"Invalid version string '{version_string}': {str(e)}")
